contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single-entry test function: attempt one call to c.play with an arbitrary amount.
    // We assert a general invariant relating pot and address(c).balance for all inputs.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this contract has enough balance to forward the requested amount
        require(address(this).balance >= amount);

        // read observable state before the call
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;
        uint balBefore = address(c).balance;

        bool reverted;
        // perform the call, capturing whether it reverted
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read observable state after the call
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;

        // compute deltas safely (avoid underflow in expressions inside assert)
        uint potIncreased = (potAfter > potBefore) ? (potAfter - potBefore) : 0;
        uint balDeltaPlus = (balAfter >= balBefore) ? (balAfter - balBefore) : 0;
        uint balDeltaMinus = (balBefore >= balAfter) ? (balBefore - balAfter) : 0;

        // General rule asserted:
        // - If the call reverted, pot and contract balance are unchanged.
        // - Otherwise (call succeeded): either pot increased by exactly 10 (ticket) or pot was reset to 0;
        //   and the change in contract balance equals the change in pot minus either 0 or 1 (fee <= 1).
        assert(
            (reverted && potAfter == potBefore && balAfter == balBefore)
            || (
                !reverted
                && (
                    // pot either increased by exactly 10 or became 0
                    potIncreased == 10 || potAfter == 0
                )
                && (
                    // balance change equals pot change (no fee) OR equals pot change minus 1 (fee of 1 paid out)
                    // We express these without negative subtraction inside assert by comparing additions.
                    (balAfter == balBefore + potIncreased)
                    || (balAfter + 1 == balBefore + potIncreased)
                )
            )
        );
    }

    // accept incoming Ether (so c.transfer to this contract won't fail if invoked)
    receive() external payable {}
}

