    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        uint balBefore = address(c).balance;
        bool reverted;
        try c.play{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        uint balAfter = address(c).balance;
        uint potIncreased = (potAfter > potBefore) ? (potAfter - potBefore) : 0;
        uint balDeltaPlus = (balAfter >= balBefore) ? (balAfter - balBefore) : 0;
        uint balDeltaMinus = (balBefore >= balAfter) ? (balBefore - balAfter) : 0;
        assertTrue((reverted && potAfter == potBefore && balAfter == balBefore)
            || (
                !reverted
                && (
                    // pot either increased by exactly 10 or became 0
                    potIncreased == 10 || potAfter == 0
                )
                && (
                    // balance change equals pot change (no fee) OR equals pot change minus 1 (fee of 1 paid out)
                    // We express these without negative subtraction inside assert by comparing additions.
                    (balAfter == balBefore + potIncreased)
                    || (balAfter + 1 == balBefore + potIncreased)
                )
            ));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
